import{_ as i,E as a,h as l,c as d,b as e,f as h,H as o,a4 as s,w as u}from"./chunks/framework.B_fYP6Of.js";const w=JSON.parse('{"title":"Build a small RAG system","description":"Add one hosted RAG feature to the app you already have. Verify each step from document import to search, model output, and a citation a reader can open.","frontmatter":{"title":"Build a small RAG system","description":"Add one hosted RAG feature to the app you already have. Verify each step from document import to search, model output, and a citation a reader can open.","teaser":"Before you add chat to the interface, ask one question and look at what your search actually found. That one passage is your first useful checkpoint."},"headers":[],"relativePath":"students/build.md","filePath":"students/build.md"}'),c={name:"students/build.md"};function p(m,t,g,f,b,y){const r=a("LabArticleHeader"),n=a("LabScroll");return l(),d("div",null,[t[1]||(t[1]=e("h1",{id:"build-one-complete-source-to-answer-path",tabindex:"-1"},[h("Build one complete source-to-answer path "),e("a",{class:"header-anchor",href:"#build-one-complete-source-to-answer-path","aria-label":'Permalink to "Build one complete source-to-answer path"'},"​")],-1)),o(r),t[2]||(t[2]=s('<p>Your first result should be a passage you can open. Choose a question, write down the sentence you expect, and keep the model turned off while you build the search. When the app returns text, check its source ID and open the original. If the passage answers the question, you have something worth handing to a model.</p><p>Use your existing FastAPI app and Docker/HTTPS setup if they already work. <a href="./from-app-studio">App Studio walkthrough</a></p><h2 id="seven-small-steps" tabindex="-1">Seven small steps <a class="header-anchor" href="#seven-small-steps" aria-label="Permalink to &quot;Seven small steps&quot;">​</a></h2><ol><li><strong>Import.</strong> Gather about five permitted documents. Give each one a stable ID and version. Keep the originals. Import a document twice and inspect what is actually stored.</li><li><strong>Prepare.</strong> For text, compare splitting by paragraph or heading with splitting at a fixed size. Open a passage that broke in an awkward place. For a graph, link each entity and relationship to the passage that supports it. <a href="./chunking">Chunking guide</a></li><li><strong>Index.</strong> If you chose vectors, generate real embeddings, record the model version, and use a compatible encoder for questions. For a graph, store the actual relationships you found. Use keyword search as a baseline for comparison. <a href="./embeddings">Embeddings guide</a></li><li><strong>Retrieve.</strong> Ask the original question with generation turned off. Look at the returned passages or graph paths. Can you see the expected evidence and its source ID?</li><li><strong>Generate.</strong> Give a real model the relevant passages it is authorized to see. Display its answer and a link to the source location. Open the link and check which words support the claim.</li><li><strong>Try missing evidence.</strong> Ask about a detail the documents leave out. Can the system tell the reader what it cannot establish? If it supplies a detail anyway, inspect the retrieved passages and model output separately.</li><li><strong>Host and verify.</strong> Open the HTTPS URL as a visitor. Keep credentials and database services private, limit public usage, and confirm that records survive a process restart. Save the working revision and your actual results.</li></ol><p>Work in one issue or small change at a time. If AI helps, ask for the smallest patch, read the important code, run the test yourself, and link the commit or pull request.</p><h2 id="what-to-show-at-each-checkpoint" tabindex="-1">What to show at each checkpoint <a class="header-anchor" href="#what-to-show-at-each-checkpoint" aria-label="Permalink to &quot;What to show at each checkpoint&quot;">​</a></h2>',6)),o(n,{kind:"table",label:"table for What to show at each checkpoint"},{default:u(()=>[...t[0]||(t[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Stage"),e("th",{scope:"col"},"Something a classmate can check")])]),e("tbody",null,[e("tr",null,[e("td",null,"Import"),e("td",null,"Source manifest, stored record, and what happened on repeat import")]),e("tr",null,[e("td",null,"Retrieval"),e("td",null,"Question, expected evidence, and the passages or graph paths actually returned")]),e("tr",null,[e("td",null,"Generation"),e("td",null,"Model/provider, the redacted context you supplied, and its actual response")]),e("tr",null,[e("td",null,"Source support"),e("td",null,"One citation a reader can open, plus one question with insufficient evidence")]),e("tr",null,[e("td",null,"Hosted operation"),e("td",null,"Working HTTPS link, durable data, safe logs, and the source revision")]),e("tr",null,[e("td",null,"Improvement"),e("td",null,"A peer’s observation, the change you made, and the result of the same check")])])],-1)])]),_:1}),t[3]||(t[3]=s('<p>For <strong>Build</strong>, demonstrate the small hosted import, retrieval, and chat path. For <strong>Checked Release</strong>, strengthen persistence, repeatable setup, evaluation, and citations. Canvas gives the official dates and instructions. <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/course/milestones.md" target="_blank" rel="noreferrer">Course milestones</a></p><h2 id="start-with-what-you-have" tabindex="-1">Start with what you have <a class="header-anchor" href="#start-with-what-you-have" aria-label="Permalink to &quot;Start with what you have&quot;">​</a></h2><p>Use your existing login, dashboard, repository, and server if they work. A <a href="./reference">local reference lab</a> lets you inspect source IDs and SQLite search before trying optional Ollama embeddings and generation. <a href="./library-survey">RAG libraries</a> are tools you can compare when you have a specific problem.</p><p>If your model is unavailable, keep building and testing real import and retrieval. Mark generation as unfinished. A fixed response can test how the page renders, but you still need to observe what a real model does with the evidence. <a href="./stuck">Troubleshooting</a> · <a href="./check">Evaluation guide</a></p>',4))])}const k=i(c,[["render",p]]);export{w as __pageData,k as default};
